import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { configuredExtractionModel } from '/Users/lizhiyao/Projects/oh-my-knowledge/dist/observability/knowledge-extraction/adapters/executor.js';
import { createExecutor } from '/Users/lizhiyao/Projects/oh-my-knowledge/dist/executors/index.js';
import { EXTRACTION_PROMPT, EXTRACTION_PROMPT_VERSION } from '/Users/lizhiyao/Projects/oh-my-knowledge/dist/observability/knowledge-extraction/prompt.js';
import { reviewDigest, authorReviewStatus } from '/Users/lizhiyao/Projects/oh-my-knowledge/dist-scripts/bench/entity-extraction-review.js';
import { parseEntityReviewCorpus, entityReviewInput } from '/Users/lizhiyao/Projects/oh-my-knowledge/dist-scripts/bench/entity-review-corpus.js';

const root = dirname(fileURLToPath(import.meta.url));
const load = path => JSON.parse(readFileSync(resolve(root, path), 'utf8'));
const manifest = load('frozen/manifest.json');
const corpus = parseEntityReviewCorpus(readFileSync(resolve(root, 'frozen/corpus.json'), 'utf8'));
const inputs = load('frozen/inputs.json');
const authorText = readFileSync(resolve(root, 'frozen/self-review.json'), 'utf8');
if (manifest.measurementId !== 'sha256:850658605f5c99ad977081b8e3f97eddef4730d3c70e1b27c9a77cfd0f78ce5b'
  || EXTRACTION_PROMPT_VERSION !== 'knowledge-extraction-v4' || reviewDigest(EXTRACTION_PROMPT) !== manifest.promptHash
  || authorReviewStatus(authorText, corpus, manifest.measurementId).status !== 'completed') throw new Error('Frozen identity/author review mismatch.');
if (inputs.length !== 16 || corpus.cases.length !== 16) throw new Error('Expected exactly 16 frozen cases.');
for (const sample of corpus.cases) {
  const input = inputs.find(value => value.caseId === sample.caseId);
  if (!input || input.inputDigest !== reviewDigest(JSON.stringify(entityReviewInput(sample)))
    || JSON.stringify(input.input) !== JSON.stringify(entityReviewInput(sample))) throw new Error('Frozen input mismatch.');
}
const plan = { measurementId: manifest.measurementId, executor: 'codex', model: 'gpt-6.1-sol', repeats: 2,
  caseCount: inputs.length, maxCalls: 32, concurrency: 2, retries: 0,
  scheduling: 'Round barrier; development and validation each run serially in parallel.',
  usdCost: 'unknown', effort: 'executor default, not explicitly set',
  backendRevision: 'not reported', sourceCommit: 'f8b6ba7eadd9b9f92eab771314bfdbe82d638625',
  allowedData: 'Frozen source excerpts and limitations, plus exact production v4 prompt. No gold, review criteria or previous output.',
  authorization: '继续按修正后的标准做两轮实体提取验收，结果你自己复核。',
  captureDriverDigest: `sha256:${createHash('sha256').update(readFileSync(fileURLToPath(import.meta.url))).digest('hex')}` };
const args = process.argv.slice(2);
if (args.length === 0) { console.log(JSON.stringify({ ...plan, mode: 'dry-run', modelCalls: 0 }, null, 2)); }
else if (args.length !== 1 || args[0] !== '--execute') throw new Error('Only --execute starts the explicitly authorized 32-call plan.');
else {
  const output = resolve(root, 'captures');
  mkdirSync(output); // One invocation only; never overwrite or resume/retry this run.
  const saveNew = (name, value) => writeFileSync(resolve(output, name), JSON.stringify(value, null, 2), { flag: 'wx' });
  const replace = (name, value) => {
    const path = resolve(output, name); const temporary = `${path}.pending`;
    writeFileSync(temporary, JSON.stringify(value, null, 2), { flag: 'wx' }); renameSync(temporary, path);
  };
  const startedAt = new Date().toISOString();
  const state = { ...plan, startedAt, status: 'running', attempted: 0, recorded: 0 };
  saveNew('plan.json', plan); saveNew('manifest.json', state);
  saveNew('prompt.json', { version: EXTRACTION_PROMPT_VERSION, prompt: EXTRACTION_PROMPT });
  const controller = new AbortController();
  const abort = () => controller.abort(); process.once('SIGINT', abort); process.once('SIGTERM', abort);
  const execute = createExecutor('codex');
  const groups = ['development', 'validation'].map(split => ({ captureVersion: 'omk-entity-captures/v1',
    measurementId: manifest.measurementId, split, repeats: 2, startedAt, executor: plan.executor, model: plan.model, records: [] }));
  for (const group of groups) saveNew(`${group.split}.json`, group);
  const worker = async (group, repeat) => {
    for (const input of inputs.filter(value => value.split === group.split)) {
      if (controller.signal.aborted) break;
      const id = `${repeat}-${input.caseId}`;
      let runtime;
