const root = dirname(fileURLToPath(import.meta.url));
const load = path => JSON.parse(readFileSync(resolve(root, path), 'utf8'));
const frozen = load('frozen/manifest.json');
const state = load('captures/manifest.json');
if (state.status !== 'captured' || state.attempted !== 32 || state.recorded !== 32) throw new Error('Capture is not complete.');
const corpus = parseEntityReviewCorpus(readFileSync(resolve(root, 'frozen/corpus.json'), 'utf8'));
const groups = ['development', 'validation'].map(split => reviewCapture(readFileSync(resolve(root, `captures/${split}.json`), 'utf8'), corpus, frozen.measurementId, checkWindowExtractionResponse));
const outcomes = groups.flatMap(group => group.records).sort((a,b) => a.repeat-b.repeat || corpus.cases.findIndex(c=>c.caseId===a.caseId)-corpus.cases.findIndex(c=>c.caseId===b.caseId));
if (outcomes.length !== 32 || new Set(outcomes.map(r=>`${r.repeat}:${r.caseId}`)).size !== 32) throw new Error('Incomplete or repeated output closure.');
const records = outcomes.map(record => {
  const id = `${record.repeat}-${record.caseId}`;
  const capture = groups.flatMap(g=>g.capture.records).find(r=>r.caseId===record.caseId && r.repeat===record.repeat);
  const runtimeText = readFileSync(resolve(root, `captures/${id}.runtime.json`), 'utf8');
  const runtime = JSON.parse(runtimeText);
  if (capture.result.captureStatus === 'output' && runtime.output !== capture.result.output) throw new Error('Output bytes differ from executor result.');
